 *   SafeBox box = new SafeBox(data);
 *   data[0] = 99;                       // must NOT affect the box
 *   box.getValues()[1] = -5;            // must NOT affect the box
 *   java.util.Arrays.toString(box.getValues()) -> "[1, 2, 3]"
 */
