import java.util.Arrays;

public class SafeBoxTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            int[] data = {1, 2, 3};
            SafeBox box = new SafeBox(data);
            check("initial contents", "[1, 2, 3]", Arrays.toString(box.getValues()));
            data[0] = 99;
            check("mutating the caller's array does not change the box", "[1, 2, 3]", Arrays.toString(box.getValues()));
            int[] out = box.getValues();
            if (out != null && out.length == 3) {
                out[1] = -5;
            }
            check("mutating the returned array does not change the box", "[1, 2, 3]", Arrays.toString(box.getValues()));
            check("getValues() is not the same array the caller passed in", false, box.getValues() == data);
            SafeBox empty = new SafeBox(new int[0]);
            check("empty box contents", "[]", Arrays.toString(empty.getValues()));
            SafeBox single = new SafeBox(new int[] {7});
            check("single element box contents", "[7]", Arrays.toString(single.getValues()));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

