import java.util.Arrays;

public class SafeBox {

    private final int[] values;

    public SafeBox(int[] values) {
        this.values = Arrays.copyOf(values, values.length);
    }

    public int[] getValues() {
        return Arrays.copyOf(values, values.length);
    }
}
